package yokai.core.ebook

import java.io.File
import yokai.core.ebook.io.FileChannelSource
import yokai.core.ebook.io.RandomAccessSource

/** Test books generated by `core/ebook/testbooks/make_testbooks.py`. */
object Fixtures {
    fun file(name: String): File {
        val url = requireNotNull(Fixtures::class.java.getResource("/fixtures/$name")) { "Missing fixture $name" }
        return File(url.toURI())
    }

    fun source(name: String): RandomAccessSource = FileChannelSource.open(file(name))

    fun bytes(name: String): ByteArray = file(name).readBytes()
}
